 $('#content').innerHTML='<div class="segments calendar-modes">'+[['upcoming','Calendrier'],['results','Résultats'],['postponed','Reports / statuts'],['missing','À vérifier']].map(([v,t])=>'<button data-mode="'+v+'" class="'+(v===mode?'active':'')+'" aria-pressed="'+(v===mode)+'">'+t+'</button>').join('')+'</div>'+calendarToolbar(rows.length)+'<p class="calendar-help">Horaires en '+esc(tz)+'. Probabilités estimées : 1 = domicile, N = nul, 2 = extérieur. Ouvre une ligne pour consulter l’analyse.</p>'+(calendarView==='details'?'<p class="calendar-sort-note">Les colonnes et le sélecteur trient les rencontres à l’intérieur de chaque journée. Le tri Horaire peut aussi inverser l’ordre des jours. Cotes : chargées avec Actualiser, puis relues sans nouvel appel.</p>':'')+(rows.length?Calendar.render(rows.slice(0,limit),{view:calendarView,sort:calendarSort,direction:calendarDirection,card})+(rows.length>limit?'<button class="loadmore" id="more">Afficher davantage</button>':''):empty(invalid?'Vérifie les dates sélectionnées.':'Aucun match dans cette sélection.',invalid?'La date de début doit précéder la date de fin.':calendarRange==='today'?'Aucune rencontre renseignée pour aujourd’hui. Consulte Demain ou les 7 prochains jours.':'Change la période, le championnat ou le filtre de statut.'));
