function renderTable(){const map=new Map();for(const m of current().rows){for(const t of [m.home,m.away])if(!map.has(t))map.set(t,{team:t,n:0,w:0,d:0,l:0,gf:0,ga:0,pts:0});if(!m.score||m.date>M.today())continue;const h=map.get(m.home),a=map.get(m.away),[x,y]=m.score;h.n++;a.n++;h.gf+=x;h.ga+=y;a.gf+=y;a.ga+=x;if(x===y){h.d++;a.d++;h.pts++;a.pts++}else{const win=x>y?h:a,lose=x>y?a:h;win.w++;win.pts+=3;lose.l++}}
 const rows=[...map.values()].sort((a,b)=>b.pts-a.pts||(b.gf-b.ga)-(a.gf-a.ga)||b.gf-a.gf||a.team.localeCompare(b.team));$('#content').innerHTML=`<div class="panel"><h2>Classement calculé</h2><p>À partir des scores renseignés uniquement. Les matchs manquants, sanctions et règles particulières de départage ne sont pas intégrés : ce tableau peut différer du classement officiel.</p><div class="tablewrap"><table><thead><tr><th>#</th><th>Équipe</th>${['J','G','N','P','Diff.','Pts'].map(t=>`<th class="num">${t}</th>`).join('')}</tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(short(r.team))}</td>${[r.n,r.w,r.d,r.l,r.gf-r.ga,r.pts].map((n,i)=>`<td class="num">${i===5?'<b>'+n+'</b>':n}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`;}
function report(metrics){
 if(!metrics)return empty('Pas encore de résultats évaluables.','Les indicateurs apparaîtront quand des résultats seront disponibles.');
 const m=metrics,delta=m.brier-m.baseline,labels=['Victoire à domicile','Match nul','Victoire à l’extérieur'],bins=m.binsByOutcome?.[calibrationOutcome]||m.bins;
 return `<div class="stats"><div class="stat"><span>Matchs évalués</span><strong>${m.n}</strong></div><div class="stat"><span>Brier · plus bas = mieux</span><strong>${m.brier.toFixed(3)}</strong></div><div class="stat"><span>Issue favorite réalisée</span><strong>${pct(m.accuracy)}</strong></div></div>
 <div class="panel"><h2>Le modèle apporte-t-il quelque chose ?</h2><p>Référence : fréquences historiques domicile / nul / extérieur. Brier de la référence : <b>${m.baseline.toFixed(3)}</b>.</p><p class="${delta<0?'positive':'negative'}">${delta<0?'Le modèle fait mieux':'Le modèle ne fait pas mieux'} sur cet échantillon (écart : ${delta.toFixed(3)}).</p><p>Perte logarithmique : ${m.logloss.toFixed(3)}. Brier : somme des erreurs au carré sur les trois issues, entre 0 et 2. Ces résultats ne garantissent pas les performances futures.</p></div>
 <div class="panel" id="calibrationPanel"><h2>Calibration · ${labels[calibrationOutcome]}</h2><div class="segments calibration-choice" aria-label="Issue à examiner">${['Domicile','Nul','Extérieur'].map((label,i)=>`<button data-calibration="${i}" class="${i===calibrationOutcome?'active':''}" aria-pressed="${i===calibrationOutcome}">${label}</button>`).join('')}</div><p>Probabilité annoncée (bleu clair) et fréquence observée (bleu foncé). Si beaucoup de matchs sont annoncés autour de 60 %, l’issue devrait se produire environ six fois sur dix.</p>
 ${bins.map((b,i)=>`<div class="calrow" aria-label="${i*20} à ${(i+1)*20} pour cent, ${b.n} matchs"><span>${i*20}–${(i+1)*20} %</span><div class="meter"><i style="width:${b.p*100}%"></i><span>${b.n?pct(b.p):'—'}</span></div><div class="meter actual"><i style="width:${b.y*100}%"></i><span>${b.n?pct(b.y):'—'}</span></div><span>${b.n} m.</span></div>`).join('')}<p class="small">Chaque tranche indique son effectif. Les groupes contenant peu de matchs sont instables. Ce graphique contrôle les probabilités ; il ne les corrige pas automatiquement.</p></div>`;
}
function tracked(){const s=selection();return archive.forecasts.filter(f=>f.match.league===s.league&&f.match.season===s.season).map(f=>{const m=D.resolve(f.match,all()),valid=m&&D.timely(f,m);return {...f,currentMatch:m,result:valid?m?.score:null,note:!m?'Rapprochement non résolu':!valid?'Horaire avancé avant l’enregistrement : exclu':m.conflict?'Conflit de sources : exclu':m.date!==f.match.date?'Report : '+date(m.date):D.labels[m.status]};});}
function recordCategory(r){return !r.currentMatch||!D.timely(r,r.currentMatch)||r.currentMatch.conflict||['CANCELLED','AWARDED'].includes(r.currentMatch.status)?'excluded':r.result&&r.currentMatch.date<=M.today()?'evaluated':'waiting';}
function scoredRecords(rows){return rows.filter(r=>recordCategory(r)==='evaluated').map(r=>({id:r.match.id,date:r.currentMatch.date,score:r.result,pred:r.pred}));}
function scopeRecords(){const rows=tracked();return trackingModel==='all'?rows:rows.filter(r=>(r.pred.version||M.VERSION)===trackingModel);}
function chartPanel(rows,{id='trackingEvolution',title='La qualité des prévisions dans le temps',label='Prévisions enregistrées',adjusted=null}={}){
 const points=I.series(rows),other=adjusted?I.series(adjusted):null;
 if(!points.length)return `<div class="panel" id="${id}"><h2>${esc(title)}</h2><p>Le graphique apparaîtra après le premier résultat évaluable d’une prévision enregistrée. Les simulations historiques restent disponibles dans Laboratoire.</p></div>`;
 const width=innerWidth<540?380:620,height=250,left=43,right=14,top=16,bottom=38,plotW=width-left-right,plotH=height-top-bottom;
 const values=points.flatMap(p=>[p.brier,p.reference]).concat(other?.map(p=>p.brier)||[]),low=Math.max(0,Math.floor((Math.min(...values)-.08)*10)/10),high=Math.min(2,Math.ceil((Math.max(...values)+.08)*10)/10);
 const from=M.day(points[0].date),to=M.day(points.at(-1).date),x=d=>left+(to===from?plotW/2:(M.day(d)-from)/(to-from)*plotW),y=v=>top+(high-v)/(high-low)*plotH;
 const line=(list,key,cls)=>`<polyline class="chart-line ${cls}" points="${list.map(p=>x(p.date).toFixed(2)+','+y(p[key]).toFixed(2)).join(' ')}"/>`;
 const ticks=Array.from({length:5},(_,i)=>low+(high-low)*i/4);
 const svg=`<svg class="chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(title)}. Brier cumulé, plus bas signifie mieux. ${points.at(-1).n} matchs."><title>${esc(title)} · Brier cumulé</title>${ticks.map(v=>`<line class="chart-grid" x1="${left}" y1="${y(v)}" x2="${width-right}" y2="${y(v)}"/><text x="${left-7}" y="${y(v)+4}" text-anchor="end">${v.toFixed(2)}</text>`).join('')}${line(points,'reference','chart-reference')}${line(points,'brier','')}${other?line(other,'brier','chart-adjusted'):''}${points.filter((p,i)=>points.length<25||i===points.length-1).map(p=>`<circle cx="${x(p.date)}" cy="${y(p.brier)}" r="3.5" fill="#587f2d"><title>${esc(date(p.date))} · ${p.n} matchs · Brier ${p.brier.toFixed(4)}</title></circle>`).join('')}<text x="${left}" y="${height-12}">${esc(date(points[0].date))}</text>${to!==from?`<text x="${width-right}" y="${height-12}" text-anchor="end">${esc(date(points.at(-1).date))}</text>`:''}</svg>`;
 return `<div class="panel" id="${id}"><h2>${esc(title)}</h2><p>Brier cumulé après chaque date de match. Une valeur plus basse indique de meilleures probabilités sur les résultats disponibles.</p>${svg}<div class="chart-legend"><span><i></i>${esc(label)}</span><span class="reference"><i></i>Fréquences historiques</span>${other?'<span class="adjusted"><i></i>Ajusté · v2</span>':''}</div><p class="small">${points.at(-1).n} matchs · les premiers points peuvent varier fortement.${other?' Comparaison sur les mêmes matchs.':' Les résultats peuvent évoluer si une source corrige un score ; les probabilités enregistrées restent figées.'}</p><details class="chart-data"><summary>Lire les valeurs (${points.length} dates)</summary><div class="tablewrap"><table><thead><tr><th>Date</th><th class="num">Matchs</th><th class="num">Brier</th><th class="num">Référence</th>${other?'<th class="num">Ajusté</th>':''}</tr></thead><tbody>${points.slice(-30).map(p=>`<tr><td>${date(p.date)}</td><td class="num">${p.n}</td><td class="num">${p.brier.toFixed(4)}</td><td class="num">${p.reference.toFixed(4)}</td>${other?`<td class="num">${other.find(q=>q.date===p.date)?.brier.toFixed(4)||'—'}</td>`:''}</tr>`).join('')}</tbody></table></div>${points.length>30?'<p class="small">Les 30 dernières dates sont affichées.</p>':''}</details></div>`;
}
