async function applySportsResponse(raw,fullLeague=null){
 const year=Number(CURRENT.slice(0,4));
 if(fullLeague&&raw.response.some(x=>x.league?.id!==D.sportsCodes[fullLeague]||x.league?.season!==year))throw Error('Le calendrier reçu ne correspond pas au championnat demandé.');
 for(const league of Object.keys(names)){
  const subset=raw.response.filter(x=>x.league?.id===D.sportsCodes[league]&&x.league?.season===year);if(!subset.length){if(league===fullLeague)throw Error('Aucune rencontre reçue pour '+names[league]+'. Dernières données conservées.');continue}
  const i=datasets.findIndex(d=>d.league===league&&d.season===CURRENT),old=datasets[i],partial={...raw,response:subset,results:subset.length},parsed=D.apiSports(partial,league,CURRENT,REG),asData=combineAS(old.asData,partial),now=raw._consultedAt||new Date().toISOString();
  const candidate=dataset({...old,asData,asCheckedAt:now,asFullCheckedAt:league===fullLeague?now:old.asFullCheckedAt,checkedAt:now,revision:await digest(JSON.stringify({open:old.data,as:asData}))},old.rows);datasets[i]=candidate;
  apiChecks.set(checkId(league,CURRENT),{state:'ok',received:candidate.asData.response.length,finals:candidate.rows.filter(m=>m.score&&m.provider==='api-sports').length,ignored:parsed.ignored.length});
 }
 saveData();
}
async function ensureLiveDay(day,{automatic}){
 const consultations=[];if(!S.status().quota)await S.request('status');
 for(const league of Object.keys(names)){
  const d=datasets.find(d=>d.league===league&&d.season===CURRENT);
  if(d.asFullCheckedAt&&calendarDay({kickoff:d.asFullCheckedAt})===day&&Date.now()-Date.parse(d.asFullCheckedAt)<5*60000&&automatic)continue;
  const raw=await S.request('fixtures',{league:D.sportsCodes[league],season:Number(CURRENT.slice(0,4))},{automatic,ttl:automatic?5*60000:50000});await applySportsResponse(raw,league);consultations.push(raw._consultedAt);
 }
 return consultations.filter(Boolean).sort()[0]||null;
}
