function spendText(s){return usd(s.session.knownCost)+(s.session.unknownCost?' connus + '+s.session.unknownCost+' coût(s) à vérifier':'')}
function auditRows(rows){return rows.slice(-100).reverse().map(r=>{
 const record=A.records().find(x=>x.id===r.id),state=r.state==='pending'?'En cours':r.state==='ok'?'Analyse reçue':'Échec',u=r.usage;
 return `<tr><td>${esc(new Date(r.at).toLocaleString('fr-FR'))}</td><td><details><summary>${esc(r.title||'Dossier ancien')}</summary><p class="small">${esc(r.scope||'—')} · ${esc(r.policy?.profile==='custom'?'Personnalisé':PROFILES_LABELS[r.policy?.profile]||'Réglages anciens')} · ${r.policy?.maxTokens||'—'} tokens de sortie maximum</p><p class="small">Identifiant : ${esc(r.generationId||'non communiqué')}<br>Fournisseur : ${esc(r.provider||'non communiqué')}<br>Source du coût : ${r.costSource==='generation'?'Vérification de la génération':u.cost!==null?'Réponse OpenRouter':'non communiqué'}</p><p class="small">${r.estimate?'Estimation avant appel : '+usd(r.estimate.value)+' (indicative).':''} ${r.durationMs!==undefined?'Durée observée : '+(r.durationMs/1000).toLocaleString('fr-FR')+' s.':''}</p>${r.error||r.auditError?'<p class="ai-error">'+esc([r.error,r.auditError].filter(Boolean).join(' '))+'</p>':''}${record?'<button data-ai-record="'+esc(r.id)+'">Lire l’analyse enregistrée</button>':''}</details></td><td>${esc(r.servedModel||r.model||'—')}<small>${r.servedModel?'Modèle renvoyé':'Modèle demandé'}</small>${r.servedModel&&r.model!==r.servedModel?'<small>Demandé : '+esc(r.model)+'</small>':''}</td><td class="num"><strong>${u.cost===null?'À vérifier':usd(u.cost)}</strong></td><td>${state}</td><td class="num">${u.promptTokens??'—'} / ${u.completionTokens??'—'}<small>Cache fournisseur : ${u.cachedTokens??'—'} · raisonnement : ${u.reasoningTokens??'—'}</small></td></tr>`;
 }).join('')||'<tr><td colspan="6">Aucun appel IA dans cette période.</td></tr>'}
const PROFILES_LABELS={economy:'Économique',balanced:'Équilibré',pro:'Pro'};
function auditModels(rows){
 const groups=new Map();for(const r of rows){const id=r.servedModel||r.model||'Non communiqué';if(!groups.has(id))groups.set(id,{calls:0,known:0,missing:0,cost:0});const g=groups.get(id);g.calls++;if(r.usage.cost===null)g.missing++;else{g.known++;g.cost+=r.usage.cost}}
 return Array.from(groups,([id,g])=>`<tr><td>${esc(id)}</td><td class="num">${g.calls}</td><td class="num">${usd(g.cost)}${g.missing?' + '+g.missing+' inconnu(s)':''}</td><td class="num">${g.known?usd(g.cost/g.known):'—'}</td></tr>`).join('')||'<tr><td colspan="4">Aucun modèle utilisé.</td></tr>';
}
function auditMarkup(){
 const a=A.audit(auditRange),s=A.status(),f=S.status(),t=a.totals;
 return `<p>Les coûts confirmés proviennent des réponses OpenRouter. Un coût absent reste <b>à vérifier</b>, même pour une tentative échouée.</p><label class="audit-filter">Période<select id="aiAuditRange"><option value="session" ${auditRange==='session'?'selected':''}>Session ouverte</option><option value="all" ${auditRange==='all'?'selected':''}>Journal conservé</option></select></label><div id="auditMetrics" class="audit-metrics">${auditMetrics(a,f)}</div><p class="small">Session depuis le ${esc(new Date(a.startedAt).toLocaleString('fr-FR'))}. Elle reprend à zéro lorsque l’application est rechargée ; le journal reste sur cet appareil. Les dépenses effectuées dans d’autres applications et l’abonnement football ne sont pas additionnés ici.</p><div class="row"><button id="reconcileAICosts" ${s.busy||s.auditBusy||s.keyState!=='ok'||!s.auditRecoverable?'disabled':''}>${s.auditBusy?'Vérification des coûts…':'Vérifier les coûts manquants'}</button><button id="exportAIAudit">Exporter la piste d’audit</button></div><p id="auditNotice" class="small" role="status">La vérification lit les métadonnées de dix générations au maximum, sans nouvelle analyse. Sans identifiant communiqué, le coût reste inconnu.</p><div class="tablewrap audit-table"><table><thead><tr><th>Date</th><th>Dossier</th><th>Modèle</th><th class="num">Coût USD</th><th>État</th><th class="num">Tokens entrée / sortie</th></tr></thead><tbody id="aiAuditRows">${auditRows(a.rows)}</tbody></table></div><p class="small" id="auditRetention">${t.calls} tentative(s) · les 100 dernières sont affichées. Le journal sauvegarde les 1 000 derniers appels ; l’export inclut aussi tous les appels de la session ouverte.</p><details><summary>Coûts par modèle</summary><div class="tablewrap"><table><thead><tr><th>Modèle</th><th class="num">Appels</th><th class="num">Coût confirmé</th><th class="num">Moyenne des coûts connus</th></tr></thead><tbody id="aiAuditModels">${auditModels(a.rows)}</tbody></table></div></details><details><summary>Comment les prix et la qualité sont suivis</summary><p>Avant un appel, le repère utilise environ un token pour trois caractères du dossier, des consignes et du schéma, puis le plafond de sortie et les prix du catalogue. C’est une estimation indicative, pas un plafond garanti. Les totaux utilisent uniquement les coûts réellement communiqués.</p><p>Les profils changent l’explication des mêmes probabilités statistiques. Leur efficacité pour prévoir les résultats n’est pas évaluée ici. L’onglet Bilan mesure les prévisions statistiques enregistrées avec leurs résultats. Une analyse plus chère ne reçoit aucune note de fiabilité supérieure par défaut.</p><p class="small"><a href="https://openrouter.ai/docs/guides/guides/usage-accounting" target="_blank" rel="noopener">OpenRouter : coûts et tokens par réponse</a></p></details>`;
}
function auditMetrics(a,f){const t=a.totals;return `<div><span>Coût IA confirmé · USD</span><strong>${usd(t.knownCost)}</strong><small>${t.unknownCost?t.unknownCost+' coût(s) à vérifier':'Tous les coûts de cette période sont connus'}</small></div><div><span>Tentatives IA</span><strong>${t.calls}</strong><small>${t.failed} échec(s) · ${t.pending} en cours</small></div><div><span>Relectures locales de la session</span><strong>${A.status().session.cacheReads}</strong><small>0 $ de nouvel appel pour ces relectures</small></div><div><span>Requêtes football · session</span><strong>${f.sessionUsage.manual+f.sessionUsage.automatic}</strong><small>${f.sessionUsage.manual} manuelles · ${f.sessionUsage.automatic} automatiques · ${f.sessionUsage.checks} vérification(s) du compte</small></div>`}
