 try{const verified=await (reuse?A.reverify():A.verify(key));if(verified&&(!A.catalog().length||Date.now()-Date.parse(A.status().catalogAt)>24*3600000))await loadAIModels()}catch(e){if(dialogMode==='connections'&&$('#aiSettingsError')){$('#aiSettingsError').hidden=false;$('#aiSettingsError').textContent=e.message}}
